]

# Let's find special values (non-5) with their section number
special_entries = []
section = 0
for r in range(len(grid)):
    row = grid[r]
    if all(c == 0 for c in row):
        section += 1
    else:
        for c, val in enumerate(row):
            if val != 5:
                special_entries.append({'section': section-1, 'row': r, 'col': c, 'val': val})

print("All special values (non-5, non-0):")
for e in special_entries:
    print(e)

# Group by section
