        by_section[s] ==[]
    by_section[s].append(e)

print("\nBy section:")
for s in sorted(by_section.keys()):
    print(f"  Section {s}: {by_section[s]}")

# Check the relationship: col 0 vs col 16
print("\n\nRelationship: col 0 vs col 16:")
for s in sorted(by_section.keys()):
    cols_by_row = {0: [], 1: []}
    for e in by_section[s]:
        cols_by_row[e['row']].append(e['col'])
    for r in cols_by_row:
        cols = sorted(cols_by_row[r])
        if len(cols) >= 2:
            print(f"  Section {s}, row {r}: cols {cols}")
        elif len(cols) == 1:
            c = cols[0]
            # Check if opposite corner is also special
            if r == 0:
                other_c = 16 if c < 16 else c
                if other_c != c:
                    for e2 in by_section[s]:
                        if e2['row'] == 0 and e2['col'] == other_c:
                            print(f"    (0,{c})={e['val']} matches (0,{other_c})={e2['val']}")
            else:
                other_c = 0 if c > 0 else c
                for e2 in by_section[s]:
                    if e2['row'] == 1 and e2['col'] == other_c:
                        print(f"    (1,{c})={e['val']} matches (1,{other_c})={e2['val']}")

